async function compressPdfLogo(file: File) {
  const source = await new Promise<HTMLImageElement>((resolve, reject) => { const image = new Image(); image.onload = () => resolve(image); image.onerror = () => reject(new Error("Imagem inválida")); image.src = URL.createObjectURL(file); });
  const scale = Math.min(1, 640 / Math.max(source.naturalWidth, source.naturalHeight));
  const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(source.naturalWidth * scale)); canvas.height = Math.max(1, Math.round(source.naturalHeight * scale));
  canvas.getContext("2d")?.drawImage(source, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/webp", 0.84);
}

const escapePrintHtml = (value: unknown) => String(value ?? "").replace(/[&<>\"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" }[char] ?? char));

function printSellerDirectory(sellers: Seller[], onFinished?: () => void, logoSource = logo) {
  const finish = () => onFinished?.();
  const printWindow = window.open("", "_blank", "width=920,height=720");
  if (!printWindow) { toast.error("Permita janelas pop-up para emitir o PDF"); finish(); return; }
  const rows = sellers.map((seller) => `<tr><td>${escapePrintHtml(seller.name)}</td><td class="total-cell">${escapePrintHtml(seller.total)}</td></tr>`).join("");
  const issuedAt = new Date().toLocaleString("pt-BR");
  const logoUrl = logoSource.startsWith("data:") ? logoSource : new URL(logoSource, window.location.href).href;
  printWindow.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Lista de revendedores</title><style>@page{size:A4;margin:12mm}body{font-family:Arial,sans-serif;color:#161616;font-size:10pt}.print-header{display:flex;align-items:center;gap:14px;border-bottom:2px solid #c9a227;padding-bottom:10px}.print-logo{width:58px;height:58px;object-fit:contain;border-radius:10px}.print-header h1{font-size:20pt;margin:0 0 5px}.print-header p{color:#555;margin:0}table{width:100%;border-collapse:collapse;margin-top:16px}th{background:#f1ecd9;text-align:left;font-size:8pt;text-transform:uppercase}th,td{border:1px solid #d8d8d8;padding:7px 6px;vertical-align:top}.total-cell{text-align:right;font-weight:700;white-space:nowrap}footer{margin-top:18px;color:#777;font-size:8pt;text-align:right}</style></head><body><header class="print-header"><img class="print-logo" src="${escapePrintHtml(logoUrl)}" alt="Logo Rainha das Capas"><div><h1>Rainha das Capas</h1><p>Lista de revendedores e mercadorias · Emitido em ${escapePrintHtml(issuedAt)}</p></div></header><table><thead><tr><th>Revendedor</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><footer>Rainha das Capas · Gestão Comercial</footer></body></html>`);
  printWindow.document.close(); printWindow.focus(); setTimeout(() => { printWindow.print(); printWindow.onafterprint = () => { printWindow.close(); finish(); }; setTimeout(finish, 2500); }, 100);
}

function printWeeklyReport({ title, weekLabel, range, type, total, orders, sellerName, sellerStatus, logoSource = logo, onFinished }: { title: string; weekLabel: string; range: string; type: string; total: string; orders: number; sellerName: string; sellerStatus: string; logoSource?: string; onFinished?: () => void }) {
  const finish = () => onFinished?.();
  const printWindow = window.open("", "_blank", "width=920,height=720");
  if (!printWindow) { toast.error("Permita janelas pop-up para emitir o PDF"); finish(); return; }
  const issuedAt = new Date().toLocaleString("pt-BR");
  const logoUrl = logoSource.startsWith("data:") ? logoSource : new URL(logoSource, window.location.href).href;
  const safeTitle = escapePrintHtml(title);
  printWindow.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${safeTitle}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#161616;margin:0;font-size:10pt}.print-header{display:flex;align-items:center;gap:14px;border-bottom:2px solid #c9a227;padding-bottom:12px;margin-bottom:18px}.print-logo{width:58px;height:58px;object-fit:contain;border-radius:10px}.print-heading{flex:1}.print-heading h1{font-size:20pt;margin:0 0 5px}.print-heading h2{font-size:13pt;margin:0 0 4px}.print-heading p{color:#555;margin:0}.meta{text-align:right;font-size:9pt;color:#555;line-height:1.5}.summary{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:18px}.summary div{border:1px solid #d8d8d8;border-radius:6px;padding:10px}.summary span{display:block;color:#666;font-size:8pt;text-transform:uppercase}.summary strong{display:block;font-size:13pt;margin-top:4px}.report-lines{border-top:1px solid #d8d8d8;border-bottom:1px solid #d8d8d8}.report-line{display:flex;justify-content:space-between;gap:16px;padding:12px 8px;border-bottom:1px solid #ededed}.report-line:last-child{border-bottom:0}.report-total{background:#f1ecd9;font-weight:700;font-size:12pt;padding:14px 8px;display:flex;justify-content:space-between}.notes{margin-top:18px;color:#555;line-height:1.5}footer{margin-top:28px;color:#777;font-size:8pt;text-align:right}</style></head><body><header class="print-header"><img class="print-logo" src="${escapePrintHtml(logoUrl)}" alt="Logo Rainha das Capas"><div class="print-heading"><h1>Rainha das Capas</h1><h2>${safeTitle}</h2><p>${escapePrintHtml(weekLabel)} · ${escapePrintHtml(range)}</p></div><div class="meta">Tipo: ${escapePrintHtml(type)}<br>Emitido em ${escapePrintHtml(issuedAt)}</div></header><section class="summary"><div><span>Situação</span><strong>${escapePrintHtml(weekLabel.includes("atual") ? "Em andamento" : "Encerrada")}</strong></div><div><span>Movimentações</span><strong>${escapePrintHtml(orders)}</strong></div><div><span>Valor total</span><strong>${escapePrintHtml(total)}</strong></div></section><section class="report-lines"><div class="report-line"><span>${escapePrintHtml(sellerName)} · ${escapePrintHtml(sellerStatus)}</span><strong>${escapePrintHtml(total)}</strong></div><div class="report-total"><span>Total da semana</span><strong>${escapePrintHtml(total)}</strong></div></section><p class="notes">Relatório gerado a partir dos dados compartilhados da operação Rainha das Capas.</p><footer>Rainha das Capas · Gestão Comercial</footer></body></html>`);
  printWindow.document.close(); printWindow.focus();
  setTimeout(() => { printWindow.print(); printWindow.onafterprint = () => { printWindow.close(); finish(); }; setTimeout(finish, 2500); }, 100);
}

function printSellerItems(seller: Seller, onFinished?: () => void, logoSource = logo) {
  const finish = () => onFinished?.();
  const printWindow = window.open("", "_blank", "width=920,height=720");
  if (!printWindow) { toast.error("Permita janelas pop-up para emitir o PDF"); finish(); return; }
  const items = seller.items ?? [];
  const issuedAt = new Date().toLocaleString("pt-BR");
  const logoUrl = logoSource.startsWith("data:") ? logoSource : new URL(logoSource, window.location.href).href;
  const rows = items.length ? items.map((row) => `<tr><td>${escapePrintHtml(row.item)}</td><td>${escapePrintHtml(row.quantity)}</td><td>${escapePrintHtml(row.unit)}</td><td>${escapePrintHtml(row.total)}</td><td>${escapePrintHtml(row.date)}</td><td>${escapePrintHtml(row.note || "—")}</td></tr>`).join("") : `<tr><td colspan="6" class="empty">Nenhum item lançado para este revendedor.</td></tr>`;
  printWindow.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Lista de ${escapePrintHtml(seller.name)}</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#161616;margin:0;font-size:10pt}.print-header{display:flex;align-items:center;gap:14px;border-bottom:2px solid #c9a227;padding-bottom:10px;margin-bottom:16px}.print-logo{width:58px;height:58px;object-fit:contain;border-radius:10px}.print-heading{flex:1}.print-heading h1{font-size:20pt;margin:0 0 5px}.print-heading h2{font-size:11pt;margin:0;color:#555;font-weight:normal}.meta{text-align:right;font-size:9pt;color:#555;line-height:1.5}.summary{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:16px}.summary div{border:1px solid #d8d8d8;border-radius:6px;padding:8px}.summary span{display:block;color:#666;font-size:8pt;text-transform:uppercase}.summary strong{display:block;font-size:12pt;margin-top:3px}table{width:100%;border-collapse:collapse}th{background:#f1ecd9;text-align:left;font-size:8pt;text-transform:uppercase}th,td{border:1px solid #d8d8d8;padding:7px 6px;vertical-align:top}td:nth-child(2){text-align:center;width:9%}td:nth-child(3),td:nth-child(4){white-space:nowrap;width:13%}.empty{text-align:center;color:#666;padding:20px}footer{margin-top:18px;color:#777;font-size:8pt;text-align:right}@media print{button{display:none}}</style></head><body><header class="print-header"><img class="print-logo" src="${escapePrintHtml(logoUrl)}" alt="Logo Rainha das Capas"><div class="print-heading"><h1>Rainha das Capas</h1><h2>Lista de mercadorias · ${escapePrintHtml(seller.name)}</h2></div><div class="meta">${escapePrintHtml(seller.phone)}<br>Situação: ${escapePrintHtml(seller.status)}<br>Emitido em ${escapePrintHtml(issuedAt)}</div></header><section class="summary"><div><span>Revendedor</span><strong>${escapePrintHtml(seller.name)}</strong></div><div><span>Itens lançados</span><strong>${items.length}</strong></div><div><span>Total</span><strong>${escapePrintHtml(seller.total)}</strong></div></section><table><thead><tr><th>Item</th><th>Qtd.</th><th>Valor unitário</th><th>Valor total</th><th>Data</th><th>Observação</th></tr></thead><tbody>${rows}</tbody></table><footer>Rainha das Capas · Gestão Comercial</footer></body></html>`);
  printWindow.document.close();
  printWindow.focus();
  const openPrintDialog = () => { printWindow.print(); printWindow.onafterprint = () => { printWindow.close(); finish(); }; setTimeout(finish, 2500); };
  if (printWindow.document.readyState === "complete") setTimeout(openPrintDialog, 100);
  else printWindow.addEventListener("load", openPrintDialog, { once: true });
}

