function formatTitle(id: string) {
  return navItems.find((item) => item.id === id)?.label ?? "Dashboard";
}
function weekOptions() { const now = new Date(); const monthNumber = now.getMonth() + 1; const month = String(monthNumber).padStart(2, "0"); const lastDay = new Date(now.getFullYear(), monthNumber, 0).getDate(); const currentWeek = Math.ceil(now.getDate() / 7); return Array.from({ length: currentWeek }, (_, index) => { const number = index + 1; const start = (number - 1) * 7 + 1; const end = Math.min(number * 7, lastDay); return { number, value: `${now.getFullYear()}-${month}-${String(number).padStart(2, "0")}`, label: `MÊS ${month} · SEMANA ${String(number).padStart(2, "0")}`, range: `${String(start).padStart(2, "0")}–${String(end).padStart(2, "0")}/${month}/${now.getFullYear()}`, current: number === currentWeek }; }); }
function currentPeriod() { const now = new Date(); const current = weekOptions().at(-1); const date = now.toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }); const time = now.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }); return { label: current?.label ?? "MÊS 01 · SEMANA 01", dateTime: `${date} · ${time}` }; }

function initialsFor(name: string) { return name.split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase(); }
function moneyNumber(value: string) { return Number(value.replace(/[^0-9,-]/g, "").replace(".", "").replace(",", ".")) || 0; }
function dashboardData(sellers: Seller[]) { const total = sellers.reduce((sum, seller) => sum + moneyNumber(seller.total), 0); const orders = sellers.reduce((sum, seller) => sum + (seller.items?.length ?? 0), 0); const paid = sellers.filter((seller) => seller.status === "Pago").reduce((sum, seller) => sum + moneyNumber(seller.total), 0); const pending = sellers.filter((seller) => seller.status === "Pendente").reduce((sum, seller) => sum + moneyNumber(seller.total), 0); const accord = sellers.filter((seller) => seller.status === "Acordo").reduce((sum, seller) => sum + moneyNumber(seller.total), 0); const profile = [0.32, 0.58, 0.44, 0.72, 1, 0.38]; const chartValues = profile.map((factor) => Math.round(orders * factor)); return { total, orders, paid, pending, accord, chartValues }; }
function chartPath(values: number[], close = false) { const max = Math.max(1, ...values); const points = values.map((value, index) => `${Math.round(index * (700 / Math.max(1, values.length - 1)))},${Math.round(175 - (value / max) * 145)}`); const path = `M${points.join(" L")}`; return close ? `${path} L700,210 L0,210 Z` : path; }
function currency(value: number) { return value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" }); }

function StatusPill({ status }: { status: string }) {
  const styles = status === "Pago" ? "status-success" : status === "Acordo" ? "status-warning" : "status-danger";
  return <span className={`status-pill ${styles}`}><span className="status-dot" />{status}</span>;
}

function MetricCard({ label, value, detail, icon: Icon, accent, trend }: { label: string; value: string; detail: string; icon: typeof Activity; accent: string; trend?: string }) {
  return (
    <article className="metric-card" style={{ "--metric-accent": accent } as React.CSSProperties}>
      <div className="metric-top"><span className="metric-label">{label}</span><span className="metric-icon"><Icon size={16} /></span></div>
      <div className="metric-value">{value}</div>
      <div className="metric-detail">{trend && <span className="trend-up"><ArrowUpRight size={13} />{trend}</span>}{detail}</div>
    </article>
  );
}

function Dashboard({ sellers, onNavigate }: { sellers: Seller[]; onNavigate: (id: string) => void }) {
  const period = currentPeriod(); const data = dashboardData(sellers); const goalPercent = Math.min(100, (data.total / 10000) * 100); const linePath = chartPath(data.chartValues); const areaPath = chartPath(data.chartValues, true);
  return (
    <div className="page-stack page-enter">
      <section className="hero-panel" style={{ backgroundImage: `linear-gradient(90deg, rgba(15,15,15,.97) 0%, rgba(15,15,15,.82) 52%, rgba(15,15,15,.35) 100%), url(${texture})` }}>
        <div className="hero-copy"><span className="eyebrow light-eyebrow">{period.label} · {period.dateTime}</span><h1>A semana sob controle<span className="gold-dot">.</span></h1><p>Uma visão precisa do que entrou, do que falta e do que move a sua operação hoje.</p><button className="gold-button" onClick={() => onNavigate("revendedores")}><Plus size={16} /> Iniciar</button></div>
      </section>

      <section className="metrics-grid">
        <MetricCard label="Revendedores ativos" value={String(sellers.length)} detail="cadastros no período atual" icon={UsersRound} accent="#C9A227" />
        <MetricCard label="Valor da semana" value={currency(data.total)} detail="meta semanal R$ 10.000" icon={CircleDollarSign} accent="#7DBB8B" />
        <MetricCard label="Pedidos registrados" value={String(data.orders)} detail="itens lançados na semana" icon={Package} accent="#8DA9CB" />
        <MetricCard label="Recebimentos pendentes" value={currency(data.pending)} detail={`${sellers.filter((seller) => seller.status === "Pendente").length} revendedores`} icon={CreditCard} accent="#D87E76" />
      </section>

      <section className="content-grid">
        <article className="panel weekly-panel"><div className="panel-header"><div><span className="eyebrow">RITMO DA SEMANA</span><h2>Movimentações</h2></div><button className="ghost-button" onClick={() => onNavigate("relatorios")}>Ver relatório <ChevronRight size={15} /></button></div><div className="chart-wrap"><div className="chart-y"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><div className="chart-area"><div className="chart-grid-lines"><i /><i /><i /><i /></div><svg viewBox="0 0 700 210" preserveAspectRatio="none" className="chart-line"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#C9A227" stopOpacity=".28" /><stop offset="100%" stopColor="#C9A227" stopOpacity="0" /></linearGradient></defs><path d={areaPath} fill="url(#area)" /><path d={linePath} fill="none" stroke="#C9A227" strokeWidth="3" /></svg><div className="chart-x">{weekly.map((item) => <span key={item.day}>{item.day}</span>)}</div></div></div><div className="chart-footer"><span><i className="legend-gold" /> Pedidos e recebimentos</span><span className="chart-total">{data.orders} movimentações <ArrowUpRight size={14} /></span></div></article>
        <article className="panel finance-panel"><div className="panel-header"><div><span className="eyebrow">RESUMO FINANCEIRO</span><h2>Saldo da semana</h2></div><button className="icon-button"><MoreHorizontal size={18} /></button></div><div className="finance-total">{currency(data.total)}</div><div className="finance-progress"><div className="finance-progress-head"><span>Meta semanal</span><strong>{goalPercent.toFixed(1).replace(".", ",")}%</strong></div><div className="progress-track"><div className="progress-fill" style={{ width: `${goalPercent}%` }} /></div></div><div className="finance-rows"><div><span className="finance-icon income"><ArrowDownRight size={15} /></span><span>Recebido</span><strong>{currency(data.paid)}</strong></div><div><span className="finance-icon pending"><Activity size={15} /></span><span>A receber</span><strong>{currency(data.pending)}</strong></div><div><span className="finance-icon accord"><ShieldCheck size={15} /></span><span>Em acordo</span><strong>{currency(data.accord)}</strong></div></div></article>
      </section>

      <section className="content-grid lower-grid"><article className="panel seller-panel"><div className="panel-header"><div><span className="eyebrow">ATUALIZAÇÕES RECENTES</span><h2>Revendedores</h2></div><button className="ghost-button" onClick={() => onNavigate("revendedores")}>Ver todos <ChevronRight size={15} /></button></div><div className="seller-list">{sellers.slice(0, 4).map((seller) => <div className="seller-row" key={seller.name}><div className="avatar">{seller.initials}</div><div className="seller-main"><strong>{seller.name}</strong><span>{seller.phone}</span></div><div className="seller-total"><strong>{seller.total}</strong><span>{seller.updated}</span></div><StatusPill status={seller.status} /></div>)}</div></article><article className="panel spotlight-panel"><div className="spotlight-image" style={{ backgroundImage: `linear-gradient(0deg, rgba(15,15,15,.8), rgba(15,15,15,.05)), url(${productStill})` }}><span className="eyebrow light-eyebrow">CATÁLOGO EM DESTAQUE</span><div><h2>Novas capas,<br /><em>mesma precisão.</em></h2><button className="light-link" onClick={() => onNavigate("mercadorias")}>Ver mercadorias <ArrowUpRight size={15} /></button></div></div></article></section>
    </div>
  );
}

function Revendedores({ sellers, pdfLogo, onSelect, onAdd, onDelete }: { sellers: Seller[]; pdfLogo?: string; onSelect: (seller: Seller) => void; onAdd: (seller: Seller) => void; onDelete: (seller: Seller) => void }) {
  const [query, setQuery] = useState("");
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [notes, setNotes] = useState("");
  const [printing, setPrinting] = useState(false);
  const filtered = useMemo(() => sellers.filter((s) => `${s.name} ${s.phone}`.toLowerCase().includes(query.toLowerCase())), [query, sellers]);
  const exportDirectory = () => { if (!filtered.length) { toast.error("Nenhum revendedor para exportar"); return; } setPrinting(true); printSellerDirectory(filtered, () => setPrinting(false), pdfLogo); };
  const saveSeller = () => { if (!name.trim() || !phone.trim()) { toast.error("Preencha nome e telefone"); return; } onAdd({ name: name.trim(), initials: initialsFor(name), phone: phone.trim(), total: "R$ 0,00", status: "Pendente", updated: "Agora", tone: "danger", items: [], avatar: notes }); setName(""); setPhone(""); setNotes(""); setOpen(false); toast.success("Revendedor cadastrado"); };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">BASE DE CLIENTES</span><h1>Revendedores</h1><p>Gerencie a carteira, acompanhe valores e abra o histórico individual.</p></div><button className="gold-button" onClick={() => setOpen(true)}><Plus size={16} /> Novo revendedor</button></div><div className="toolbar"><div className="search-box"><Search size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Pesquisar por nome ou telefone" /></div><button className="outline-button"><Filter size={16} /> Filtros</button><button className="outline-button">Esta semana <ChevronDown size={15} /></button></div><article className="panel table-panel"><div className="table-caption"><span>{filtered.length} revendedores encontrados</span><button className="ghost-button" onClick={exportDirectory} disabled={printing}>{printing ? "Preparando PDF…" : <><FileDown size={15} /> Exportar lista</>}</button></div><div className="table-scroll"><table><thead><tr><th>Nome</th><th>Telefone</th><th>Total da semana</th><th>Situação</th><th>Última atualização</th><th /></tr></thead><tbody>{filtered.map((seller) => <tr key={seller.name} onClick={() => onSelect(seller)}><td><div className="table-person"><div className="avatar small">{seller.initials}</div><strong>{seller.name}</strong></div></td><td>{seller.phone}</td><td className="money-cell">{seller.total}</td><td><StatusPill status={seller.status} /></td><td className="muted-cell">{seller.updated}</td><td><div className="row-actions"><button className="row-delete" aria-label={`Remover ${seller.name}`} onClick={(event) => { event.stopPropagation(); if (window.confirm(`Remover o revendedor ${seller.name}?`)) onDelete(seller); }}><Trash2 size={15} /></button><ChevronRight size={17} className="row-arrow" /></div></td></tr>)}</tbody></table></div></article>{open && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setOpen(false)}><div className="modal-card"><div className="modal-header"><div><span className="eyebrow">NOVO CADASTRO</span><h2>Adicionar revendedor</h2></div><button className="icon-button" onClick={() => setOpen(false)}><X size={18} /></button></div><label>Nome completo<input value={name} onChange={(e) => setName(e.target.value)} placeholder="Ex.: Juliana Martins" autoFocus /></label><label>Telefone<input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="(00) 00000-0000" /></label><label>Observações<textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Opcional" rows={3} /></label><div className="modal-actions"><button className="outline-button" onClick={() => setOpen(false)}>Cancelar</button><button className="gold-button" onClick={saveSeller}><Save size={15} /> Salvar revendedor</button></div></div></div>}</div>;
}

function Payments({ sellers, onStatusChange }: { sellers: Seller[]; onStatusChange: (seller: Seller, status: string) => void }) {
  const [filter, setFilter] = useState("Todos");
  const [open, setOpen] = useState(false);
  const [selectedClientId, setSelectedClientId] = useState(sellers[0]?.clientId ?? "");
  const [paymentStatus, setPaymentStatus] = useState("Pago");
  const data = dashboardData(sellers);
  const visible = filter === "Todos" ? sellers : sellers.filter((s) => s.status === filter.slice(0, -1) || s.status === filter);
  const registerPayment = () => {
    const seller = sellers.find((item) => item.clientId === selectedClientId) ?? sellers[0];
    if (!seller) { toast.error("Nenhum revendedor disponível"); return; }
    onStatusChange(seller, paymentStatus);
    setOpen(false);
    toast.success(`Pagamento de ${seller.name} registrado como ${paymentStatus.toLowerCase()}`);
  };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">CONTROLE DE CAIXA</span><h1>Pagamentos</h1><p>Altere o status e mantenha a semana financeira em ordem.</p></div><button className="gold-button" onClick={() => { setSelectedClientId(sellers[0]?.clientId ?? ""); setPaymentStatus("Pago"); setOpen(true); }}><Plus size={16} /> Registrar pagamento</button></div><div className="payment-summary"><div><span>Total pago</span><strong className="green-text">{currency(data.paid)}</strong><small>{sellers.filter((seller) => seller.status === "Pago").length} revendedores</small></div><div><span>Total pendente</span><strong className="red-text">{currency(data.pending)}</strong><small>{sellers.filter((seller) => seller.status === "Pendente").length} revendedores</small></div><div><span>Total em acordo</span><strong className="gold-text">{currency(data.accord)}</strong><small>{sellers.filter((seller) => seller.status === "Acordo").length} revendedores</small></div></div><div className="filter-tabs">{["Todos", "Pendentes", "Pagos", "Acordos"].map((item) => <button className={filter === item ? "active" : ""} key={item} onClick={() => setFilter(item)}>{item}</button>)}</div><article className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Nome</th><th>Telefone</th><th>Valor</th><th>Situação</th><th>Último pagamento</th><th>Observações</th></tr></thead><tbody>{visible.map((seller) => <tr key={seller.clientId ?? seller.name}><td><div className="table-person"><div className="avatar small">{seller.initials}</div><strong>{seller.name}</strong></div></td><td>{seller.phone}</td><td className="money-cell">{seller.total}</td><td><label className="status-select-wrap"><StatusPill status={seller.status} /><select className="status-select" value={seller.status} onChange={(event) => { onStatusChange(seller, event.target.value); toast.success(`Status de ${seller.name} atualizado`); }}><option>Pendente</option><option>Pago</option><option>Acordo</option></select><ChevronDown size={13} /></label></td><td className="muted-cell">{seller.updated}</td><td className="muted-cell">{seller.status === "Acordo" ? "Parcelamento combinado" : seller.status === "Pago" ? "Pagamento registrado" : "—"}</td></tr>)}</tbody></table></div></article>{open && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setOpen(false)}><div className="modal-card payment-modal"><div className="modal-header"><div><span className="eyebrow">NOVA BAIXA</span><h2>Registrar pagamento</h2></div><button className="icon-button" onClick={() => setOpen(false)}><X size={18} /></button></div><label>Revendedor<select value={selectedClientId} onChange={(event) => setSelectedClientId(event.target.value)}>{sellers.map((seller) => <option key={seller.clientId ?? seller.name} value={seller.clientId ?? seller.name}>{seller.name} · {seller.total}</option>)}</select></label><label>Situação após o registro<select value={paymentStatus} onChange={(event) => setPaymentStatus(event.target.value)}><option>Pago</option><option>Pendente</option><option>Acordo</option></select></label><p className="modal-helper">O valor total do revendedor é mantido e os indicadores do dashboard e desta aba são atualizados imediatamente.</p><div className="modal-actions"><button className="outline-button" onClick={() => setOpen(false)}>Cancelar</button><button className="gold-button" onClick={registerPayment}><Check size={15} /> Confirmar pagamento</button></div></div></div>}</div>;
}

function WeeksModule({ sellers }: { sellers: Seller[] }) {
  const weeks = weekOptions(); const [selected, setSelected] = useState(weeks.at(-1)); const data = dashboardData(sellers); const selectedLabel = selected?.label ?? "Semana atual";
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">HISTÓRICO OPERACIONAL</span><h1>Semanas</h1><p>Acompanhe a semana atual e consulte períodos anteriores do mês.</p></div><button className="gold-button" onClick={() => window.print()}><Printer size={15} /> Imprimir semana</button></div><div className="weeks-layout"><article className="panel weeks-list"><div className="panel-header"><div><span className="eyebrow">CALENDÁRIO DO MÊS</span><h2>Semanas disponíveis</h2></div><CalendarDays size={19} /></div>{weeks.slice().reverse().map((item) => <button key={item.value} className={`week-card ${selected?.value === item.value ? "selected" : ""}`} onClick={() => setSelected(item)}><span className="week-number">{String(item.number).padStart(2, "0")}</span><span><strong>{item.label}</strong><small>{item.range}{item.current ? " · Semana atual" : " · Período encerrado"}</small></span><ChevronRight size={16} /></button>)}</article><article className="panel week-report report-print-area"><div className="report-header"><div><span className="eyebrow">RAINHA DAS CAPAS · ANÁPOLIS-GO</span><h2>{selectedLabel}</h2><p>{selected?.range ?? ""} · Consulta de histórico</p></div><div className="report-mark">RC</div></div><div className="report-type"><span>SITUAÇÃO</span><strong>{selected?.current ? "Em andamento" : "Encerrada"}</strong><span>VALOR REGISTRADO</span><strong>{currency(data.total)}</strong></div><div className="report-lines"><div><span>João Carlos · {sellers[0]?.status ?? "Pendente"}</span><strong>{currency(data.total)}</strong></div><div><span>Movimentações</span><strong>{data.orders}</strong></div><div className="report-total"><span>Total da semana</span><strong>{currency(data.total)}</strong></div></div><div className="report-actions no-print"><button className="outline-button" onClick={() => window.print()}><Printer size={15} /> Imprimir / salvar PDF</button><button className="ghost-button" onClick={() => toast.success(`${selectedLabel} selecionada`)}>Selecionar semana</button></div></article></div></div>;
}

function MercadoriasModule({ stores, onChange }: { stores: CatalogStore[]; onChange: (stores: CatalogStore[]) => void }) {
  const [activeStoreId, setActiveStoreId] = useState(stores[0]?.id ?? "yuri"); const store = stores.find((item) => item.id === activeStoreId) ?? stores[0]; const [popup, setPopup] = useState<{ kind: "category" | "subcategory"; categoryId?: string } | null>(null); const [popupName, setPopupName] = useState("");
  const ask = (label: string) => window.prompt(label, "")?.trim() ?? "";
  const addCategory = () => { setPopup({ kind: "category" }); setPopupName(""); };
  const addSubcategory = (categoryId: string) => { setPopup({ kind: "subcategory", categoryId }); setPopupName(""); };
  const savePopup = () => { const name = popupName.trim(); if (!name || !store || !popup) { toast.error("Informe um nome"); return; } if (popup.kind === "category") onChange(stores.map((item) => item.id === store.id ? { ...item, categories: [...item.categories, { id: newId("category"), name, subcategories: [] }] } : item)); else onChange(stores.map((item) => item.id === store.id ? { ...item, categories: item.categories.map((category) => category.id === popup.categoryId ? { ...category, subcategories: [...category.subcategories, { id: newId("subcategory"), name, items: [] }] } : category) } : item)); setPopup(null); setPopupName(""); toast.success(popup.kind === "category" ? "Categoria criada" : "Subcategoria criada"); };
  const addItem = (categoryId: string, subcategoryId: string) => { if (!store) return; const name = ask("Nome da nova mercadoria"); if (!name) return; onChange(stores.map((item) => item.id === store.id ? { ...item, categories: item.categories.map((category) => category.id === categoryId ? { ...category, subcategories: category.subcategories.map((sub) => sub.id === subcategoryId ? { ...sub, items: [...sub.items, { id: newId("item"), name }] } : sub) } : category) } : item)); toast.success("Mercadoria adicionada"); };
  const rename = (kind: string, current: string, save: (name: string) => void) => { const name = window.prompt(`Editar ${kind}`, current)?.trim(); if (name && name !== current) save(name); };
  const remove = (label: string, action: () => void) => { if (window.confirm(`Remover ${label}?`)) { action(); toast.success(`${label} removido`); } };
  const updateStore = (transform: (store: CatalogStore) => CatalogStore) => { if (store) onChange(stores.map((item) => item.id === store.id ? transform(item) : item)); };
  const printStore = () => { document.body.classList.add("printing-catalog"); const cleanup = () => { document.body.classList.remove("printing-catalog"); window.removeEventListener("afterprint", cleanup); }; window.addEventListener("afterprint", cleanup); window.print(); window.setTimeout(cleanup, 1500); };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">CATÁLOGO DE MERCADORIAS</span><h1>Mercadorias</h1><p>Organize itens por loja, categoria e subcategoria, mantendo o catálogo editável.</p></div><button className="gold-button no-print" onClick={printStore}><Printer size={15} /> Imprimir lista da loja</button></div><div className="store-tabs no-print">{stores.map((item) => <button key={item.id} className={item.id === store?.id ? "active" : ""} onClick={() => setActiveStoreId(item.id)}><Store size={15} />{item.name}</button>)}</div><article className="panel catalog-panel catalog-print-sheet"><div className="catalog-head"><div><span className="eyebrow">LOJA SELECIONADA</span><h2>{store?.name}</h2></div><span className="catalog-count">{store?.categories.reduce((sum, category) => sum + category.subcategories.reduce((inner, sub) => inner + sub.items.length, 0), 0) ?? 0} itens cadastrados</span></div>{store?.categories.length ? <div className="catalog-tree">{store.categories.map((category) => <section className="catalog-category" key={category.id}><div className="catalog-category-head"><div><span className="catalog-kicker">CATEGORIA</span><h3>{category.name}</h3></div><div className="catalog-actions"><button className="icon-button" title="Editar categoria" onClick={() => rename("categoria", category.name, (name) => updateStore((current) => ({ ...current, categories: current.categories.map((item) => item.id === category.id ? { ...item, name } : item) })))}><Edit3 size={14} /></button><button className="icon-button danger-icon" title="Remover categoria" onClick={() => remove(`categoria ${category.name}`, () => updateStore((current) => ({ ...current, categories: current.categories.filter((item) => item.id !== category.id) })))}><Trash2 size={14} /></button><button className="outline-button small-button" onClick={() => addSubcategory(category.id)}><Plus size={14} /> Subcategoria</button></div></div>{category.subcategories.length ? <div className="subcategories-grid">{category.subcategories.map((sub) => <div className="subcategory-card" key={sub.id}><div className="subcategory-head"><div><span className="catalog-kicker">SUBCATEGORIA</span><strong>{sub.name}</strong></div><div className="catalog-actions"><button className="icon-button" title="Editar subcategoria" onClick={() => rename("subcategoria", sub.name, (name) => updateStore((current) => ({ ...current, categories: current.categories.map((item) => item.id === category.id ? { ...item, subcategories: item.subcategories.map((entry) => entry.id === sub.id ? { ...entry, name } : entry) } : item) })))}><Edit3 size={13} /></button><button className="icon-button danger-icon" title="Remover subcategoria" onClick={() => remove(`subcategoria ${sub.name}`, () => updateStore((current) => ({ ...current, categories: current.categories.map((item) => item.id === category.id ? { ...item, subcategories: item.subcategories.filter((entry) => entry.id !== sub.id) } : item) })))}><Trash2 size={13} /></button></div></div><div className="catalog-items">{sub.items.map((entry) => <div className="catalog-item" key={entry.id}><Package size={14} /><span>{entry.name}</span><button className="catalog-item-edit" title="Editar item" onClick={() => rename("item", entry.name, (name) => updateStore((current) => ({ ...current, categories: current.categories.map((item) => item.id === category.id ? { ...item, subcategories: item.subcategories.map((entrySub) => entrySub.id === sub.id ? { ...entrySub, items: entrySub.items.map((value) => value.id === entry.id ? { ...value, name } : value) } : entrySub) } : item) })))}><Edit3 size={13} /></button><button className="catalog-item-delete" title="Remover item" onClick={() => remove(`item ${entry.name}`, () => updateStore((current) => ({ ...current, categories: current.categories.map((item) => item.id === category.id ? { ...item, subcategories: item.subcategories.map((entrySub) => entrySub.id === sub.id ? { ...entrySub, items: entrySub.items.filter((value) => value.id !== entry.id) } : entrySub) } : item) })))}><Trash2 size={13} /></button></div>)}<button className="catalog-add-item" onClick={() => addItem(category.id, sub.id)}><Plus size={13} /> Adicionar item</button></div></div>)}</div> : <button className="catalog-add-item" onClick={() => addSubcategory(category.id)}><Plus size={13} /> Criar primeira subcategoria</button>}</section>)}</div> : <div className="catalog-empty"><Boxes size={25} /><h2>Catálogo vazio nesta loja</h2><p>Comece criando uma categoria, como iPhone, e depois adicione subcategorias e itens.</p><button className="gold-button" onClick={addCategory}><Plus size={16} /> Criar categoria</button></div>}</article>{popup && <div className="modal-backdrop no-print" onMouseDown={(event) => event.target === event.currentTarget && setPopup(null)}><div className="modal-card compact-modal"><div className="modal-header"><div><span className="eyebrow">CATÁLOGO</span><h2>{popup.kind === "category" ? "Nova categoria" : "Nova subcategoria"}</h2></div><button className="icon-button" onClick={() => setPopup(null)}><X size={18} /></button></div><label>Nome<input autoFocus value={popupName} onChange={(event) => setPopupName(event.target.value)} onKeyDown={(event) => event.key === "Enter" && savePopup()} placeholder={popup.kind === "category" ? "Ex.: iPhone" : "Ex.: Capas"} /></label><div className="modal-actions"><button className="outline-button" onClick={() => setPopup(null)}>Cancelar</button><button className="gold-button" onClick={savePopup}><Save size={15} /> Salvar</button></div></div></div>}</div>;
}

function GenericModule({ id }: { id: string }) {
  const info: Record<string, { eyebrow: string; title: string; desc: string; icon: typeof Archive; items: string[] }> = { relatorios: { eyebrow: "VISÃO CONSOLIDADA", title: "Relatório semanal", desc: "Escolha a semana, filtre por situação e prepare uma leitura simples ou detalhada.", icon: FileBarChart, items: ["Relatório simples", "Relatório detalhado", "Exportar PDF", "Compartilhar"] }, mercadorias: { eyebrow: "ESTOQUE ADMINISTRATIVO", title: "Mercadorias", desc: "Duas lojas, uma operação organizada e um catálogo pronto para crescer.", icon: Boxes, items: ["Loja 01 · Yuri", "Loja 02 · Amanda", "Categorias", "Importar Excel"] }, semanas: { eyebrow: "HISTÓRICO OPERACIONAL", title: "Semanas", desc: "Consulte cada semana exatamente como ela foi fechada.", icon: CalendarDays, items: ["Semana 33 · atual", "Semana 32", "Semana 31", "Semana 30"] }, configuracoes: { eyebrow: "PREFERÊNCIAS DO SISTEMA", title: "Configurações", desc: "Empresa, administrador, semana operacional e sincronização em um só lugar.", icon: Settings2, items: ["Dados da empresa", "Definição da semana", "Backup e restauração", "Tema e sincronização"] } };
  const current = info[id] ?? info.relatorios; const Icon = current.icon;
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">{current.eyebrow}</span><h1>{current.title}</h1><p>{current.desc}</p></div><button className="gold-button" onClick={() => toast.success("Ação preparada para este módulo") }><Plus size={16} /> Nova ação</button></div><div className="module-layout"><article className="module-intro panel"><div className="module-icon"><Icon size={26} /></div><h2>Organização que acompanha o ritmo.</h2><p>Este espaço está preparado para receber dados reais, permissões e exportações da operação Rainha das Capas.</p><button className="outline-button" onClick={() => toast("Módulo em preparação", { description: "A interface está pronta para a próxima etapa de integração." })}>Conhecer estrutura <ChevronRight size={15} /></button></article><div className="module-list">{current.items.map((item, index) => <button key={item} className="module-card" onClick={() => toast(`${item} selecionado`)}><span className="module-index">0{index + 1}</span><span><strong>{item}</strong><small>{index === 0 ? "Atualizado hoje" : "Configurar e consultar"}</small></span><ChevronRight size={17} /></button>)}</div></div></div>;
}

function ReportsModule({ sellers, reports, pdfLogo, onReportsChange }: { sellers: Seller[]; reports: SharedReport[]; pdfLogo?: string; onReportsChange: (reports: SharedReport[]) => void }) {
  const data = dashboardData(sellers); const availableWeeks = weekOptions(); const currentWeek = availableWeeks.at(-1); const [open, setOpen] = useState(false); const [printing, setPrinting] = useState(false); const report = reports.at(-1) ?? null; const [title, setTitle] = useState("Relatório semanal"); const [type, setType] = useState("Detalhado"); const [week, setWeek] = useState(currentWeek?.value ?? "");
  const generateWeeklyPdf = () => { if (!report) return; const selectedWeek = availableWeeks.find((item) => item.value === report.week); setPrinting(true); printWeeklyReport({ title: report.title, weekLabel: selectedWeek?.label ?? report.week, range: selectedWeek?.range ?? "", type: report.type, total: currency(data.total), orders: data.orders, sellerName: sellers[0]?.name ?? "Operação geral", sellerStatus: sellers[0]?.status ?? "Pendente", logoSource: pdfLogo, onFinished: () => setPrinting(false) }); };
  const createReport = () => { if (!title.trim()) { toast.error("Informe um título para o relatório"); return; } onReportsChange([...reports, { id: newId("report"), title: title.trim(), type, week, createdAt: Date.now() }]); setOpen(false); toast.success("Relatório criado"); };
  const shareReport = async () => { if (!report) return; const text = `${report.title} · ${report.type} · ${report.week} · Rainha das Capas`; try { if (navigator.share) await navigator.share({ title: report.title, text }); else { await navigator.clipboard.writeText(text); toast.success("Resumo copiado para compartilhar"); } } catch { toast("Compartilhamento cancelado"); } };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">VISÃO CONSOLIDADA</span><h1>Relatório semanal</h1><p>Crie um resumo simples ou detalhado da operação e imprima quando precisar.</p></div><button className="gold-button" onClick={() => setOpen(true)}><Plus size={16} /> Criar relatório</button></div>{report ? <article className="panel report-preview report-print-area"><div className="report-header"><div><span className="eyebrow">RAINHA DAS CAPAS · ANÁPOLIS-GO</span><h2>{report.title}</h2><p>{availableWeeks.find((item) => item.value === report.week)?.label ?? report.week} · {availableWeeks.find((item) => item.value === report.week)?.range ?? ""} · Gerado agora</p></div><div className="report-mark">RC</div></div><div className="report-type"><span>TIPO</span><strong>{report.type}</strong><span>VALOR TOTAL</span><strong>{currency(data.total)}</strong></div><div className="report-lines"><div><span>João Carlos · {sellers[0]?.status ?? "Pendente"}</span><strong>{currency(data.total)}</strong></div><div className="report-total"><span>Total geral</span><strong>{currency(data.total)}</strong></div></div><div className="report-actions no-print"><button className="outline-button" onClick={generateWeeklyPdf} disabled={printing}>{printing ? "Preparando PDF…" : <><Printer size={15} /> Imprimir / salvar PDF</>}</button><button className="outline-button" onClick={shareReport}><Share2 size={15} /> Compartilhar</button><button className="ghost-button" onClick={() => setOpen(true)}>Editar relatório</button></div></article> : <div className="empty-report panel"><div className="module-icon"><FileBarChart size={25} /></div><h2>Nenhum relatório criado ainda</h2><p>Escolha a semana e o tipo de relatório para gerar uma visualização pronta para impressão e compartilhamento.</p><button className="gold-button" onClick={() => setOpen(true)}><Plus size={16} /> Criar primeiro relatório</button></div>}{open && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setOpen(false)}><div className="modal-card"><div className="modal-header"><div><span className="eyebrow">NOVO DOCUMENTO</span><h2>Criar relatório</h2></div><button className="icon-button" onClick={() => setOpen(false)}><X size={18} /></button></div><label>Título<input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Ex.: Fechamento da semana" /></label><label>Semana<select value={week} onChange={(e) => setWeek(e.target.value)}>{availableWeeks.map((item) => <option key={item.value} value={item.value}>{item.label} · {item.range}{item.current ? " · atual" : ""}</option>)}</select></label><label>Tipo<select value={type} onChange={(e) => setType(e.target.value)}><option>Simples</option><option>Detalhado</option></select></label><div className="modal-actions"><button className="outline-button" onClick={() => setOpen(false)}>Cancelar</button><button className="gold-button" onClick={createReport}><FileBarChart size={15} /> Gerar relatório</button></div></div></div>}</div>;
}

function SettingsModule({ profileName, profilePhoto, pdfLogo, darkMode, onNameChange, onPhotoChange, onPdfLogoChange, onThemeChange }: { profileName: string; profilePhoto?: string; pdfLogo?: string; darkMode: boolean; onNameChange: (name: string) => void; onPhotoChange: (photo: string) => void; onPdfLogoChange: (photo?: string) => void; onThemeChange: (value: boolean) => void }) {
  const [name, setName] = useState(profileName);
  const [permission, setPermission] = useState<NotificationPermission>(() => typeof Notification === "undefined" ? "default" : Notification.permission);
  const [processingLogo, setProcessingLogo] = useState(false);
  const handlePdfLogo = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setProcessingLogo(true); try { onPdfLogoChange(await compressPdfLogo(file)); toast.success("Logo dos PDFs atualizado"); } catch { toast.error("Não foi possível processar o logotipo"); } finally { setProcessingLogo(false); event.target.value = ""; } };
  const [notificationsEnabled, setNotificationsEnabled] = useState(() => typeof localStorage !== "undefined" && localStorage.getItem("rainha-notifications") === "true");
  const saveLocalProfile = () => { onNameChange(name.trim() || "Administrador"); toast.success("Perfil atualizado"); };
  const toggleNotifications = async () => { if (!("Notification" in window)) { toast.error("Seu navegador não oferece notificações"); return; } if (!notificationsEnabled) { const next = await Notification.requestPermission(); setPermission(next); if (next === "granted") { localStorage.setItem("rainha-notifications", "true"); setNotificationsEnabled(true); toast.success("Notificações ativadas"); } else toast.error("Permissão de notificações não concedida"); } else { localStorage.setItem("rainha-notifications", "false"); setNotificationsEnabled(false); toast.success("Notificações desativadas"); } };
  const updatePwa = async () => { if (!("serviceWorker" in navigator)) { toast.error("Atualizações PWA não disponíveis neste navegador"); return; } const registration = await navigator.serviceWorker.ready; await registration.update(); if (registration.waiting) { registration.waiting.postMessage({ type: "SKIP_WAITING" }); window.location.reload(); } else toast.success("Aplicativo verificado: você já está na versão atual"); };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">PREFERÊNCIAS DO SISTEMA</span><h1>Configurações</h1><p>Gerencie identidade, notificações, atualização do PWA e aparência.</p></div><button className="gold-button" onClick={saveLocalProfile}><Save size={15} /> Salvar alterações</button></div><div className="settings-grid"><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">ADMINISTRADOR</span><h2>Seu perfil</h2></div><UserRound size={19} /></div><div className="profile-editor"><div className="profile-photo-wrap">{profilePhoto ? <img src={profilePhoto} alt="Foto do perfil" className="profile-photo" /> : <div className="avatar profile-avatar">{initialsFor(profileName)}</div>}<span className="muted-cell">Edite sua foto em Meu perfil</span></div><div className="profile-fields"><label>Nome exibido<input value={name} onChange={(e) => setName(e.target.value)} placeholder="Nome" /></label><p>Este nome será exibido na barra lateral e no avatar do cabeçalho.</p></div></div></article><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">IDENTIDADE DOS PDFs</span><h2>Logotipo personalizado</h2></div><FileDown size={19} /></div><div className="profile-editor"><div className="profile-photo-wrap">{pdfLogo ? <img src={pdfLogo} alt="Logotipo personalizado" className="profile-photo" /> : <div className="avatar profile-avatar"><Store size={24} /></div>}<label className="outline-button profile-photo-button"><Camera size={15} /> {processingLogo ? "Processando…" : "Selecionar logo"}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => void handlePdfLogo(event)} hidden /></label></div><div className="profile-fields"><p>Esse logotipo será usado no cabeçalho dos PDFs individual e geral. A imagem é comprimida antes de ser salva neste dispositivo.</p>{pdfLogo && <button className="ghost-button" onClick={() => onPdfLogoChange(undefined)}>Usar logo oficial</button>}</div></div></article><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">PWA · NOTIFICAÇÕES</span><h2>Alertas da operação</h2></div><Bell size={19} /></div><div className="preference-row"><div><strong>Notificações</strong><small>{permission === "granted" ? "Permissão concedida neste dispositivo" : "Receba avisos quando houver novidades"}</small></div><button className={`status-toggle ${notificationsEnabled ? "active" : "inactive"}`} onClick={() => void toggleNotifications()}>{notificationsEnabled ? "Ativas" : "Desativadas"}</button></div><button className="outline-button settings-wide-action" onClick={() => void updatePwa()}><Download size={15} /> Verificar atualização do aplicativo</button></article><article className="panel settings-card"><div className="settings-card-head"><div><span className="eyebrow">APARÊNCIA</span><h2>Tema da interface</h2></div>{darkMode ? <Moon size={19} /> : <Sun size={19} />}</div><div className="theme-choice"><button className={!darkMode ? "selected" : ""} onClick={() => onThemeChange(false)}><Sun size={20} /><span><strong>Modo claro</strong><small>Contraste suave para uso durante o dia</small></span>{!darkMode && <Check size={16} />}</button><button className={darkMode ? "selected" : ""} onClick={() => onThemeChange(true)}><Moon size={20} /><span><strong>Modo escuro premium</strong><small>Superfícies grafite e menor luminosidade</small></span>{darkMode && <Check size={16} />}</button></div></article></div></div>;
}

function SellerDetail({ seller, pdfLogo, onBack, onAddItem, onDeleteItem }: { seller: Seller; pdfLogo?: string; onBack: () => void; onAddItem: (item: SellerItem) => void; onDeleteItem: (item: SellerItem) => void }) {
  const [open, setOpen] = useState(false);
  const [printing, setPrinting] = useState(false); const [item, setItem] = useState(""); const [quantity, setQuantity] = useState("1"); const [unit, setUnit] = useState(""); const [note, setNote] = useState("");
  const items = seller.items ?? []; const total = items.reduce((sum, row) => sum + Number(row.total.replace(/[^0-9,-]/g, "").replace(".", "").replace(",", ".")), 0);
  const generatePdf = () => { setPrinting(true); printSellerItems(seller, () => setPrinting(false), pdfLogo); };
  const saveItem = () => { const qty = Number(quantity); const price = Number(unit.replace(",", ".")); if (!item.trim() || !qty || !price) { toast.error("Preencha item, quantidade e valor unitário"); return; } onAddItem({ item: item.trim(), quantity: qty, unit: currency(price), total: currency(qty * price), date: "Agora", note }); setItem(""); setQuantity("1"); setUnit(""); setNote(""); setOpen(false); toast.success("Item adicionado e total recalculado"); };
  return <div className="page-stack page-enter"><button className="back-link" onClick={onBack}>← Voltar para revendedores</button><div className="detail-header"><div className="detail-person"><div className="avatar large">{seller.initials}</div><div><span className="eyebrow">PERFIL DO REVENDEDOR</span><h1>{seller.name}</h1><p>{seller.phone} · Cadastrado em 12 ago, 2026</p></div></div><div className="detail-actions"><button className="outline-button" onClick={generatePdf} disabled={printing}>{printing ? "Preparando PDF…" : <><FileDown size={16} /> Emitir PDF</>}</button><button className="gold-button" onClick={() => toast.success("Link de compartilhamento copiado")}><Share2 size={16} /> Compartilhar</button></div></div><section className="detail-metrics"><div><span>Valor total</span><strong>{currency(total)}</strong></div><div><span>Semana atual</span><strong>Semana 33</strong></div><div><span>Situação</span><StatusPill status={seller.status} /></div></section><article className="panel table-panel"><div className="panel-header"><div><span className="eyebrow">MOVIMENTAÇÕES</span><h2>Lista de itens</h2></div><button className="gold-button" onClick={() => setOpen(true)}><Plus size={16} /> Adicionar item</button></div><div className="table-scroll"><table><thead><tr><th>Item</th><th>Quantidade</th><th>Valor unitário</th><th>Valor total</th><th>Data</th><th>Observação</th><th /></tr></thead><tbody>{items.map((row) => <tr key={`${row.item}-${row.date}`}><td><strong>{row.item}</strong></td><td>{row.quantity}</td><td>{row.unit}</td><td className="money-cell">{row.total}</td><td className="muted-cell">{row.date}</td><td className="muted-cell">{row.note || "—"}</td><td><button className="row-delete" aria-label={`Remover ${row.item}`} onClick={() => { if (window.confirm(`Remover o item ${row.item}?`)) onDeleteItem(row); }}><Trash2 size={15} /></button></td></tr>)}</tbody></table></div></article>{open && <div className="modal-backdrop" onMouseDown={(event) => event.target === event.currentTarget && setOpen(false)}><div className="modal-card"><div className="modal-header"><div><span className="eyebrow">NOVA MOVIMENTAÇÃO</span><h2>Adicionar item</h2></div><button className="icon-button" onClick={() => setOpen(false)}><X size={18} /></button></div><label>Descrição do item<input value={item} onChange={(e) => setItem(e.target.value)} placeholder="Ex.: Capa iPhone 15" autoFocus /></label><div className="form-row"><label>Quantidade<input type="number" min="1" value={quantity} onChange={(e) => setQuantity(e.target.value)} /></label><label>Valor unitário<input inputMode="decimal" value={unit} onChange={(e) => setUnit(e.target.value)} placeholder="18,00" /></label></div><label>Observação<textarea value={note} onChange={(e) => setNote(e.target.value)} rows={3} placeholder="Opcional" /></label><div className="modal-actions"><button className="outline-button" onClick={() => setOpen(false)}>Cancelar</button><button className="gold-button" onClick={saveItem}><Save size={15} /> Salvar item</button></div></div></div>}</div>;
}


function ProfileModule({ profileName, profilePhoto, userEmail, userId, activities, onSaved, onPhotoSaved }: { profileName: string; profilePhoto?: string; userEmail?: string | null; userId?: string; activities: ActivityEntry[]; onSaved: (name: string) => void; onPhotoSaved: (photo: string) => void }) {
  const [draftName, setDraftName] = useState(profileName);
  const [processingPhoto, setProcessingPhoto] = useState(false);
  const handlePhoto = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; setProcessingPhoto(true); try { onPhotoSaved(await cropAndCompressProfileImage(file)); toast.success("Foto atualizada"); } catch { toast.error("Não foi possível processar a foto"); } finally { setProcessingPhoto(false); event.target.value = ""; } };
  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">IDENTIDADE DA CONTA</span><h1>Meu perfil</h1><p>Atualize seu nome, sua foto e consulte a identidade da conta autenticada.</p></div><span className="admin-badge"><ShieldCheck size={15} /> Usuário autenticado</span></div><article className="panel profile-card"><span className="eyebrow">DADOS DO COLABORADOR</span><div className="profile-editor"><div className="profile-photo-wrap">{profilePhoto ? <img src={profilePhoto} alt="Foto do perfil" className="profile-photo" /> : <div className="avatar large">{initialsFor(profileName)}</div>}<label className="outline-button profile-photo-button"><Camera size={15} /> {processingPhoto ? "Processando…" : "Selecionar foto"}<input type="file" accept="image/*" onChange={(event) => void handlePhoto(event)} hidden /></label></div><div className="profile-fields"><label className="profile-name-field">Nome exibido<input value={draftName} onChange={(event) => setDraftName(event.target.value)} placeholder="Seu nome" /></label><p className="profile-email">{userEmail ?? "Conta Google autorizada"}<br />ID da sessão: {userId?.slice(0, 12) ?? "—"}<br />A foto é recortada e comprimida antes de ser salva neste dispositivo.</p><button className="gold-button profile-save-button" onClick={() => { if (!draftName.trim()) return; onSaved(draftName.trim()); toast.success("Perfil atualizado"); }}><Save size={15} /> Salvar alterações</button></div></div></article><article className="panel profile-card activity-history"><div className="settings-card-head"><div><span className="eyebrow">AUDITORIA PESSOAL</span><h2>Histórico de atividades</h2></div><Activity size={19} /></div>{activities.length ? <div className="activity-list">{activities.slice(0, 12).map((entry) => <div className="activity-row" key={entry.id}><span className="activity-dot" /><div><strong>{entry.action}</strong><small>{new Date(entry.createdAt).toLocaleString("pt-BR")}</small></div></div>)}</div> : <p className="profile-email">Nenhuma atividade registrada nesta conta neste dispositivo.</p>}</article></div>;
}

export default function Home() {
  const [active, setActive] = useState("dashboard");
  const [selectedSeller, setSelectedSeller] = useState<Seller | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(() => typeof window === "undefined" || window.innerWidth > 760);
  const touchStartX = useRef<number | null>(null);
  const [profileName, setProfileName] = useState("Usuário");
  const [profilePhoto, setProfilePhoto] = useState<string | undefined>();
  const [pdfLogo, setPdfLogo] = useState<string | undefined>();
  const [accountOpen, setAccountOpen] = useState(false);
  const { theme, toggleTheme } = useTheme();
  const darkMode = theme === "dark";
  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);
  const seedSellerData = useMemo(() => sellers as SharedSeller[], []);
  const seedCatalogData = useMemo(() => catalogSeed as SharedCatalogStore[], []);
  const workspace = useSharedWorkspace(seedSellerData, seedCatalogData);
  const sellerList = workspace.sellers as Seller[];
  const catalogStores = workspace.catalog as CatalogStore[];
  const reports = workspace.reports;
  const session = workspace.session;
  const [activities, setActivities] = useState<ActivityEntry[]>([]);
  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  useEffect(() => { if (!session.user) return; const key = `rainha-activity-${session.user.uid}`; const stored = localStorage.getItem(key); if (stored) { try { setActivities(JSON.parse(stored) as ActivityEntry[]); } catch { setActivities([]); } } else setActivities([]); }, [session.user]);
  useEffect(() => { if (!session.user) return; const prefix = `rainha-profile-${session.user.uid}`; setProfileName(localStorage.getItem(`${prefix}-name`) || session.user.displayName || session.user.email?.split("@")[0] || "Usuário"); setProfilePhoto(localStorage.getItem(`${prefix}-photo`) || undefined); setPdfLogo(localStorage.getItem(`rainha-pdf-logo-${session.user.uid}`) || undefined); }, [session.user]);
  useEffect(() => { const online = () => setIsOnline(true); const offline = () => setIsOnline(false); window.addEventListener("online", online); window.addEventListener("offline", offline); return () => { window.removeEventListener("online", online); window.removeEventListener("offline", offline); }; }, []);
  useEffect(() => { const onInstall = (event: Event) => { event.preventDefault(); setInstallPrompt(event as InstallPromptEvent); }; window.addEventListener("beforeinstallprompt", onInstall); return () => window.removeEventListener("beforeinstallprompt", onInstall); }, []);
  const installApp = async () => { if (!installPrompt) return; await installPrompt.prompt(); await installPrompt.userChoice; setInstallPrompt(null); };
  const navigate = (id: string) => { setSelectedSeller(null); setActive(id); if (typeof window !== "undefined" && window.innerWidth <= 760) setSidebarOpen(false); };
  const handleSidebarTouchStart = (event: TouchEvent<HTMLElement>) => { touchStartX.current = event.changedTouches[0]?.clientX ?? null; };
  const handleSidebarTouchEnd = (event: TouchEvent<HTMLElement>) => { const start = touchStartX.current; const end = event.changedTouches[0]?.clientX ?? null; touchStartX.current = null; if (start !== null && end !== null && start - end > 55) setSidebarOpen(false); };
  const recordActivity = (action: string) => { const entry = { id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, action, createdAt: Date.now() }; setActivities((current) => { const next = [entry, ...current].slice(0, 50); if (session.user) localStorage.setItem(`rainha-activity-${session.user.uid}`, JSON.stringify(next)); return next; }); toast.success(action); };
  const setSellers = (next: Seller[] | ((current: Seller[]) => Seller[])) => workspace.setSellers((current) => (typeof next === "function" ? next(current as Seller[]) : next) as SharedSeller[]);
  const setCatalog = (next: CatalogStore[] | ((current: CatalogStore[]) => CatalogStore[])) => workspace.setCatalog((current) => (typeof next === "function" ? next(current as CatalogStore[]) : next) as SharedCatalogStore[]);
  const setReports = (next: SharedReport[] | ((current: SharedReport[]) => SharedReport[])) => workspace.setReports((current) => (typeof next === "function" ? next(current) : next));
  const addSeller = (seller: Seller) => { const next = { ...seller, clientId: seller.clientId ?? `seller-${Date.now()}` }; setSellers((current) => [...current, next]); recordActivity("Revendedor compartilhado"); };
  const addItem = (item: SellerItem) => { if (!selectedSeller) return; const nextItem = { ...item, clientId: item.clientId ?? `item-${Date.now()}` }; const items = [...(selectedSeller.items ?? []), nextItem]; const next = { ...selectedSeller, items, total: currency(items.reduce((sum, row) => sum + moneyNumber(row.total), 0)), updated: "Agora" }; setSellers((current) => current.map((seller) => seller.clientId === next.clientId ? next : seller)); setSelectedSeller(next); recordActivity("Item compartilhado"); };
  const deleteSeller = (seller: Seller) => { setSellers((current) => current.filter((item) => item.clientId !== seller.clientId)); setSelectedSeller(null); recordActivity("Revendedor removido"); };
  const updateStatus = (seller: Seller, status: string) => { const next = { ...seller, status, tone: status === "Pago" ? "success" : status === "Acordo" ? "warning" : "danger", updated: "Agora" }; setSellers((current) => current.map((item) => item.clientId === seller.clientId ? next : item)); if (selectedSeller?.clientId === seller.clientId) setSelectedSeller(next); recordActivity("Pagamento atualizado"); };
  const deleteItem = (item: SellerItem) => { if (!selectedSeller) return; const items = (selectedSeller.items ?? []).filter((row) => row.clientId !== item.clientId); const next = { ...selectedSeller, items, total: currency(items.reduce((sum, row) => sum + moneyNumber(row.total), 0)), updated: "Agora" }; setSellers((current) => current.map((seller) => seller.clientId === next.clientId ? next : seller)); setSelectedSeller(next); recordActivity("Item removido"); };
  const activeLabel = selectedSeller ? selectedSeller.name : formatTitle(active);
  const saveProfileName = (name: string) => { setProfileName(name); if (session.user) localStorage.setItem(`rainha-profile-${session.user.uid}-name`, name); };
  const saveProfilePhoto = (photo: string) => { setProfilePhoto(photo); if (session.user) localStorage.setItem(`rainha-profile-${session.user.uid}-photo`, photo); };
  const savePdfLogo = (photo?: string) => { setPdfLogo(photo); if (session.user) { const key = `rainha-pdf-logo-${session.user.uid}`; if (photo) localStorage.setItem(key, photo); else localStorage.removeItem(key); } };
  if (session.loading || (session.user && !workspace.ready)) return <div className="auth-screen"><div className="auth-card auth-loading"><Activity className="spin" size={24} /><span>{session.user ? "Conectando ao espaço compartilhado…" : "Verificando sessão…"}</span></div></div>;
  if (!session.user) {
    const standaloneIos = isIosStandalone();
    const safariUrl = typeof window !== "undefined" ? window.location.href : "https://yurihbo.github.io/Rainhadascapas/";
    return <div className="auth-screen"><div className="auth-card"><div className="brand-mark auth-logo"><img src={logo} alt="Rainha das Capas" /></div><span className="eyebrow">RAINHA DAS CAPAS · ACESSO PRIVADO</span>{standaloneIos ? <><h1>Entre pelo Safari</h1><p>O login Google com verificação em duas etapas não pode ser concluído dentro do aplicativo instalado no iPhone. Abra esta mesma página no Safari para entrar sem ficar preso no loop.</p><a className="gold-button auth-login-button" href={safariUrl} target="_blank" rel="noopener noreferrer"><Smartphone size={16} /> Abrir no Safari para entrar</a><small className="auth-hint">Depois de entrar, mantenha o Safari como atalho principal para esta conta.</small></> : <><h1>Entre para continuar</h1><p>Use uma das contas Google autorizadas para acessar a operação compartilhada.</p>{session.error && <small className="auth-error">{session.error}</small>}<button className="gold-button auth-login-button" onClick={() => void session.signIn()}><LogOut size={16} /> Entrar com Google</button></>}</div></div>;
  }
  return <div className={`app-shell ${sidebarOpen ? "sidebar-open" : "sidebar-collapsed"} ${darkMode ? "theme-dark" : ""}`}>
    {sidebarOpen && <button className="mobile-overlay" aria-label="Fechar menu" onClick={() => setSidebarOpen(false)} />}<aside className="sidebar" onTouchStart={handleSidebarTouchStart} onTouchEnd={handleSidebarTouchEnd}><div className="brand"><div className="brand-mark"><img src={logo} alt="" /></div><div><strong>RAINHA</strong><span>DAS CAPAS</span></div></div><div className="workspace-switcher"><div className="store-mark"><Store size={15} /></div><div><strong>Operação compartilhada</strong><small>FireStore · operação sincronizada</small></div><ChevronDown size={14} /></div><nav className="main-nav"><span className="nav-caption">MENU PRINCIPAL</span>{navItems.filter(({ id }) => id !== "usuarios" && id !== "perfil").map(({ id, label, icon: Icon }) => <button key={id} className={active === id && !selectedSeller ? "active" : ""} onClick={() => navigate(id)}><Icon size={18} /><span>{label}</span></button>)}<button className={active === "perfil" && !selectedSeller ? "active" : ""} onClick={() => navigate("perfil")}><UserRound size={18} /><span>Meu perfil</span></button></nav><div className="sidebar-bottom"><button className="profile-button" onClick={() => setAccountOpen((value) => !value)} title="Abrir menu da conta"><div className="avatar tiny">{profilePhoto ? <img src={profilePhoto} alt="" className="avatar-image" /> : initialsFor(profileName)}</div><span><strong>{profileName}</strong><small>{session.user?.email ?? "Conta autorizada"}</small></span><MoreHorizontal size={16} /></button>{accountOpen && <div className="account-menu"><button onClick={() => { navigate("perfil"); setAccountOpen(false); }}><UserRound size={15} /> Meu perfil</button><button onClick={() => void session.logout()}><LogOut size={15} /> Sair da conta</button></div>}</div></aside>
    <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setSidebarOpen((v) => !v)}><Menu size={19} /></button><button className="collapse-button" onClick={() => setSidebarOpen((v) => !v)}>{sidebarOpen ? <PanelLeftClose size={18} /> : <PanelLeftOpen size={18} />}</button><div className="breadcrumb"><span>Rainha das Capas</span><ChevronRight size={14} /><strong>{activeLabel}</strong></div></div><div className="topbar-right"><span className={`connection-status ${isOnline ? "online" : "offline"}`} title={isOnline ? "Conectado" : "Sem conexão"}><Wifi size={14} /></span>{installPrompt && <button className="install-pwa-button" onClick={() => void installApp()} title="Instalar aplicativo"><Download size={16} /> <span>Instalar</span></button>}<button className="topbar-icon"><Search size={18} /></button><button className="topbar-icon notification"><Bell size={18} /><i /></button><div className="top-avatar">{profilePhoto ? <img src={profilePhoto} alt="" className="avatar-image" /> : initialsFor(profileName)}</div></div></header>{workspace.syncError && <div className="sync-error-banner" role="alert">{workspace.syncError}</div>}<div className="content-area">{selectedSeller ? <SellerDetail seller={selectedSeller} pdfLogo={pdfLogo} onBack={() => setSelectedSeller(null)} onAddItem={addItem} onDeleteItem={deleteItem} /> : active === "dashboard" ? <Dashboard sellers={sellerList} onNavigate={navigate} /> : active === "revendedores" ? <Revendedores sellers={sellerList} pdfLogo={pdfLogo} onSelect={setSelectedSeller} onAdd={addSeller} onDelete={deleteSeller} /> : active === "pagamentos" ? <Payments sellers={sellerList} onStatusChange={updateStatus} /> : active === "relatorios" ? <ReportsModule sellers={sellerList} reports={reports} pdfLogo={pdfLogo} onReportsChange={setReports} /> : active === "mercadorias" ? <MercadoriasModule stores={catalogStores} onChange={setCatalog} /> : active === "semanas" ? <WeeksModule sellers={sellerList} /> : active === "perfil" ? <ProfileModule profileName={profileName} profilePhoto={profilePhoto} userEmail={session.user?.email} userId={session.user?.uid} activities={activities} onSaved={saveProfileName} onPhotoSaved={saveProfilePhoto} /> : active === "configuracoes" ? <SettingsModule profileName={profileName} profilePhoto={profilePhoto} pdfLogo={pdfLogo} darkMode={darkMode} onNameChange={saveProfileName} onPhotoChange={saveProfilePhoto} onPdfLogoChange={savePdfLogo} onThemeChange={(value) => { if (value !== darkMode) toggleTheme?.(); }} /> : <GenericModule id={active} />}</div><footer className="app-footer"><span>Rainha das Capas · Gestão Comercial</span><span>Espaço compartilhado em tempo real</span></footer></main>
  </div>;
}
